        boolean warm(){boolean ready=true;for(int x=(center.getX()-16)>>4;x<=(center.getX()+16)>>4;x++)for(int z=(center.getZ()-16)>>4;z<=(center.getZ()+16)>>4;z++)ready&=level.areEntitiesLoaded(net.minecraft.world.level.ChunkPos.pack(x,z));boolean visible=level.getEntities((Entity)null,new AABB(origin.add(-16,-5,-16),origin.add(16,30,16)),e->e==beta).contains(beta);require(++warmTicks<=100,"entity residency timeout visible="+visible+" beta="+beta.position()+" level="+beta.level().dimension());return ready&&visible;}
