        ItemEntity token(boolean bob,int count){var t=new ItemEntity(level,origin.x,origin.y,origin.z,new ItemStack(bob?LbcCreatureDropItem.Kind.OLD_BOB.item():LbcDroneDropItem.ITEM,count));t.setThrower(alpha);t.setTarget(beta.getUUID());t.setNoGravity(true);t.setDeltaMovement(Vec3.ZERO);t.setPickUpDelay(1000);require(level.addFreshEntity(t),"native token admission");tokens.add(t);return t;}
        Zombie bob(){clear();var t=token(true,2);require(game.items().creatureDrops().ready(t,LbcCreatureDrops.Kind.BOB_OLD)&&game.items().specialDrops().spawn(t)&&t.getItem().getCount()==1,"Bob one shared debit");require(!game.items().specialDrops().spawn(t),"same tick one dispatch");t.discard();capture();var list=mine.stream().filter(e->e instanceof Zombie).toList();require(list.size()==1,"one native adult Bob");return (Zombie)list.getFirst();}
