        void restorePlayers(){alphaState.restore(game);betaState.restore(game);alpha.getStats().setValue(alpha,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.MOB_KILLS),alphaKills);beta.getStats().setValue(beta,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.MOB_KILLS),betaKills);}
        public void close(){close(true);}
        void close(boolean players){game.items().timeStop().end(level);clear();level.getBlockTicks().clearArea(bounds);level.getFluidTicks().clearArea(bounds);for(var e:blocks.entrySet()){if(level.getBlockEntity(e.getKey()) instanceof net.minecraft.world.Container c)c.clearContent();game.maps().restoreSnapshot(level,e.getKey(),e.getValue());}level.getBlockTicks().clearArea(bounds);level.getFluidTicks().clearArea(bounds);blockTicks.forEach(level.getBlockTicks()::schedule);fluidTicks.forEach(level.getFluidTicks()::schedule);for(long key:forced)level.setChunkForced(net.minecraft.world.level.ChunkPos.getX(key),net.minecraft.world.level.ChunkPos.getZ(key),false);level.getGameRules().set(GameRules.MOB_DROPS,mobDrops,game.server());level.getGameRules().set(GameRules.TNT_EXPLODES,tntExplodes,game.server());game.config().tntProtection=protection;game.items().indirectKills().clear(alpha);game.items().indirectKills().clear(beta);if(players)restorePlayers();}
