    private static void failure(State s,Throwable e){try{s.close();}catch(Throwable cleanup){if(cleanup!=e)e.addSuppressed(cleanup);}running=null;stopping=null;}
    public static void run(GameController game){require(running==null&&stopping==null&&retained==null,"already running");running=new State(game);try{running.initialize();}catch(RuntimeException|Error e){failure(running,e);throw e;}}
    public static void tick(GameController game){if(stopping!=null){var s=stopping;if(game.server().getTickCount()==s.lastTick)return;s.lastTick=game.server().getTickCount();try{game.items().timeStop().end(s.level);s.place();if(!s.warm()){game.items().timeStop().begin(s.level,200);return;}var cart=s.drone();s.droneConfig(cart);s.emit(cart);var b=s.token(true,1);require(game.items().creatureDrops().spawn(b,LbcCreatureDrops.Kind.BOB_OLD),"native Bob stop actor");b.discard();s.capture();stopActors=List.copyOf(s.mine);require(stopActors.size()==6,"actual Bob plus native drone graph and generated TNT/pig retained");stopEpoch=game.items().epoch();stopDebris.clear();s.level.getAllEntities().forEach(stopDebris::add);s.restorePlayers();game.items().timeStop().begin(s.level,200);stopToken=s.token(false,3);require(!game.items().specialDrops().spawn(stopToken)&&stopToken.getItem().getCount()==3,"actual stop pending token freeze");retained=s;stopping=null;SkyWars2.LOGGER.info("[check] PASS bob-drone-drops-stop-probe");}catch(Throwable e){failure(s,e);SkyWars2.LOGGER.error("[check] FAIL bob-drone-drops-stop-probe",e);}return;}if(running==null)return;var s=running;try{if(s.step()){s.close();running=null;SkyWars2.LOGGER.info("[check] PASS bob-drone-drops");}}catch(Throwable e){failure(s,e);SkyWars2.LOGGER.error("[check] FAIL bob-drone-drops",e);}}
    public static void stopProbe(GameController game){require(game.playing()&&running==null&&stopping==null&&retained==null,"actual stop probe");stopping=new State(game);try{stopping.initialize();}catch(RuntimeException|Error e){failure(stopping,e);throw e;}}
    public static void cleanup(GameController game){require(retained!=null&&stopEpoch!=null&&!game.items().currentEpoch(stopEpoch)&&stopToken!=null&&stopToken.entityTags().contains(stopEpoch)&&stopToken.getItem().getCount()==3&&stopActors.size()==6&&stopActors.stream().allMatch(Entity::isRemoved),"actual match stop quietly removes native producer graph/Bob/TNT/pig and invalidates pending epoch");require(!game.items().specialDrops().spawn(stopToken),"actual stopped pending token cannot replay");for(var e:retained.level.getAllEntities())require(stopDebris.contains(e)||(!(e instanceof ItemEntity)&&e.getType()!=EntityTypes.EXPERIENCE_ORB)||!retained.bounds.isInside(e.blockPosition())||e==stopToken,"actual stop emits no native loot/XP from retained actors");stopToken.discard();retained.close(false);retained=null;stopToken=null;stopEpoch=null;stopActors=List.of();stopDebris.clear();SkyWars2.LOGGER.info("[check] PASS bob-drone-drops-cleanup");}
